import"chrome://resources/ash/common/cr_elements/cr_button/cr_button.js";import{BaseSetupPageElement}from"./base_setup_page.js";import{UserAction}from"./cloud_upload.mojom-webui.js";import{CloudUploadBrowserProxy}from"./cloud_upload_browser_proxy.js";import{getTemplate}from"./office_setup_complete_page.html.js";export class OfficeSetupCompletePageElement extends BaseSetupPageElement{setOfficeAsDefaultHandler=true;constructor(){super()}setDefaultHandlerOnPageShown(setOfficeAsDefaultHandler){this.setOfficeAsDefaultHandler=setOfficeAsDefaultHandler;if(this.isConnected){this.connectedCallback()}}get proxy(){return CloudUploadBrowserProxy.getInstance()}connectedCallback(){super.connectedCallback();this.innerHTML=getTemplate();const uploadButton=this.querySelector(".action-button");if(this.setOfficeAsDefaultHandler){this.proxy.handler.setOfficeAsDefaultHandler()}uploadButton.addEventListener("click",(()=>this.onUploadButtonClick()))}onUploadButtonClick(){this.proxy.handler.respondWithUserActionAndClose(UserAction.kConfirmOrUploadToOneDrive)}}customElements.define("complete-page",OfficeSetupCompletePageElement);